float rand(vec2 co)
{
  return fract(sin(dot(co.xy, vec2(12.9898,78.233))) * 43758.5453);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord/iResolution.y);//*iTime for cool effect

    vec2 tilingResolution = vec2(6.0,9.0);

    vec2 tileCoordinates= (floor(uv* tilingResolution));

    vec2 blockCoordinates= fract(uv* tilingResolution);

    vec2 randomisedBlockCenter = vec2(mix(0.1,0.9,rand(tileCoordinates/tilingResolution)));

    //calc distance
    float distanceFromCentre = distance(randomisedBlockCenter, blockCoordinates);

    float centreFactor = (distanceFromCentre -1.0);

    float fragmentColour = pow(centreFactor,2.0);

    //addon
    float anim = length(tileCoordinates*5.0);
    anim= sin(anim +iTime);


    //output
    fragColor = vec4(fragmentColour,anim,0.5,0.5);
}
